# initialize_fims ----
## Setup ----
data <- FIMSFrame(data_big)

default_parameters <- setup_default_parameters(data = data)

# The report of a default model at its starting values.
get_fleet_report <- function(data) {
  frame <- FIMSFrame(data)
  setup_default_parameters(frame) |>
    initialize_fims(data = frame) |>
    fit_fims(optimize = FALSE) |>
    get_report()
}

## IO correctness ----
test_that("`initialize_fims()` works with correct inputs", {
  #' @description Test that `initialize_fims()` does not warn when all recruitment process values are estimated.
  expect_no_warning(
    result <- initialize_fims(parameters = default_parameters, data = data)
  )
  #' @description Test that `initialize_fims()` returns a list.
  expect_type(result, "list")
  #' @description Test that `initialize_fims()` returns an output with correct names.
  expect_named(
    result,
    c(
      "parameters", "map", "random", "model_data", "parameter_table",
      "tibble", "frame"
    )
  )
})

test_that("`initialize_fims()` sets up the modules named in `parameters`", {
  input <- initialize_fims(parameters = default_parameters, data = data)
  population <- input[["model_data"]][["populations"]][["population"]]
  #' @description Test that `initialize_fims()` sets up Beverton-Holt recruitment with `log_devs` as the recruitment process.
  expect_equal(
    population[["module_types"]][c("recruitment", "recruitment_process")],
    list(recruitment = "BevertonHolt", recruitment_process = "log_devs")
  )
  #' @description Test that `initialize_fims()` sets up empirical weight-at-age growth.
  expect_equal(population[["module_types"]][["growth"]], "EWAA")
  #' @description Test that `initialize_fims()` sets up logistic maturity.
  expect_equal(population[["module_types"]][["maturity"]], "Logistic")
  #' @description Test that `initialize_fims()` links both fleets to the population.
  expect_equal(population[["fleets"]], c("fleet1", "survey1"))
  #' @description Test that `initialize_fims()` sets up logistic selectivity for each fleet.
  expect_equal(
    purrr::map_chr(
      input[["model_data"]][["fleets"]],
      \(fleet) fleet[["module_types"]][["selectivity"]]
    ),
    c(fleet1 = "Logistic", survey1 = "Logistic")
  )
})

test_that("`initialize_fims()` sets up a fleet's weight at age, ageing error, and units", {
  fleet1 <- initialize_fims(
    parameters = default_parameters,
    data = data
  )[["model_data"]][["fleets"]][["fleet1"]]
  #' @description Test that `initialize_fims()` leaves weight at age empty for a fleet without its own rows, so the population weight is used.
  expect_null(fleet1[["weight_at_age"]])
  #' @description Test that `initialize_fims()` leaves ageing error empty for a fleet without ageing error rows.
  expect_null(fleet1[["ageing_error"]])
  #' @description Test that `initialize_fims()` sets catch in mt to be fit as weight.
  expect_equal(fleet1[["observed_catch_units"]], "weight")
})

test_that("`initialize_fims()` passes catch and index data only for fleets that have them", {
  likelihoods <- initialize_fims(
    parameters = default_parameters,
    data = data
  )[["model_data"]][["likelihoods"]]
  names(likelihoods) <- purrr::map_chr(likelihoods, "name")
  #' @description Test that `initialize_fims()` passes the catch of a fleet with catch to the model.
  expect_equal(
    likelihoods[["fleet1_catch"]][["observed"]],
    model_catch(data, "fleet1")
  )
  #' @description Test that `initialize_fims()` passes no catch for a fleet without catch.
  expect_null(likelihoods[["survey1_catch"]])
  #' @description Test that `initialize_fims()` passes the index of a fleet with an index to the model.
  expect_equal(
    likelihoods[["survey1_index"]][["observed"]],
    model_index(data, "survey1")
  )
  #' @description Test that `initialize_fims()` passes no index for a fleet without an index.
  expect_null(likelihoods[["fleet1_index"]])
})

test_that("`initialize_fims()` passes composition data with the expected dimensions and values", {
  fleet1 <- initialize_fims(
    parameters = default_parameters,
    data = data
  )[["model_data"]][["fleets"]][["fleet1"]]
  # Proportions are passed as counts, using the multinomial sample size.
  expected_comp <- function(comp_type) {
    data |>
      get_data() |>
      dplyr::filter(type == comp_type, fleet == "fleet1") |>
      dplyr::mutate(
        out = observed * unlist(
          parse_data_distribution(.data[["uncertainty"]])[["size"]],
          use.names = FALSE
        )
      ) |>
      dplyr::pull(out)
  }
  #' @description Test that `initialize_fims()` passes age-composition data with 1 row per year and 1 column per age.
  expect_equal(
    dim(fleet1[["age_comp"]]),
    c(get_n_years(data), get_n_ages(data))
  )
  #' @description Test that the age-composition data passed by `initialize_fims()` have the correct values.
  expect_equal(c(t(fleet1[["age_comp"]])), expected_comp("age_comp"))
  #' @description Test that `initialize_fims()` passes length-composition data with 1 row per year and 1 column per length bin.
  expect_equal(
    dim(fleet1[["length_comp"]]),
    c(get_n_years(data), get_n_lengths(data))
  )
  #' @description Test that the length-composition data passed by `initialize_fims()` have the correct values.
  expect_equal(c(t(fleet1[["length_comp"]])), expected_comp("length_comp"))
})

test_that("`initialize_fims()` fits catch and index to the expected quantity matching their units", {
  weight_report <- get_fleet_report(data_big)
  number_report <- get_fleet_report(dplyr::mutate(
    data_big,
    unit = dplyr::if_else(type %in% c("catch", "index"), "number", unit)
  ))

  #' @description Test that catch and index in mt are fit to expected weight.
  expect_equal(weight_report[["catch_expected"]][[1]], weight_report[["catch_weight"]][[1]])
  expect_equal(weight_report[["index_expected"]][[2]], weight_report[["index_weight"]][[2]])
  #' @description Test that catch and index in numbers are fit to expected numbers.
  expect_equal(number_report[["catch_expected"]][[1]], number_report[["catch_numbers"]][[1]])
  expect_equal(number_report[["index_expected"]][[2]], number_report[["index_numbers"]][[2]])
  #' @description Test that expected numbers differ from expected weight, so the checks above can tell the 2 units apart.
  expect_false(isTRUE(all.equal(
    number_report[["catch_numbers"]][[1]],
    number_report[["catch_weight"]][[1]]
  )))
  expect_false(isTRUE(all.equal(
    number_report[["index_numbers"]][[2]],
    number_report[["index_weight"]][[2]]
  )))
})

test_that("`initialize_fims()` passes a fleet's own weight at age to the model", {
  fleet_default_rows <- dplyr::filter(
    data_big,
    type == "weight_at_age",
    timing == 1
  ) |>
    dplyr::mutate(fleet = "fleet1", timing = NA_integer_, observed = observed * 2)
  fleet_year_5_rows <- dplyr::mutate(
    fleet_default_rows,
    timing = 5L,
    observed = observed / 2 * 3
  )
  base_report <- get_fleet_report(data_big)
  fleet_report <- get_fleet_report(
    dplyr::bind_rows(data_big, fleet_default_rows, fleet_year_5_rows)
  )
  n_ages <- get_n_ages(data)
  year_5_index <- (5 - get_start_year(data)) * n_ages + seq_len(n_ages)
  base_catch_weight <- base_report[["catch_weight_at_age"]][[1]]
  fleet_catch_weight <- fleet_report[["catch_weight_at_age"]][[1]]

  #' @description Test that a fleet's weight at age sets its catch weight at age, with year 5 using that year's rows and other years the fleet default.
  expect_equal(fleet_catch_weight[year_5_index], 3 * base_catch_weight[year_5_index])
  expect_equal(fleet_catch_weight[-year_5_index], 2 * base_catch_weight[-year_5_index])
  #' @description Test that another fleet without its own weight at age keeps the population weight for its index weight.
  expect_equal(
    fleet_report[["index_weight_at_age"]][[2]],
    base_report[["index_weight_at_age"]][[2]]
  )
  #' @description Test that a fleet's weight at age does not change population biomass.
  expect_equal(fleet_report[["biomass"]], base_report[["biomass"]])
})

test_that("`initialize_fims()` uses a fleet's own age-to-length conversion rows", {
  # fleet1 gets a uniform table and survey1 keeps the shared table.
  conversion <- dplyr::filter(data_big, type == "age_to_length_conversion")
  uniform_probability <- 1 / dplyr::n_distinct(conversion[["length"]])
  fleet_data <- FIMSFrame(dplyr::bind_rows(
    data_big,
    dplyr::mutate(conversion, fleet = "fleet1", observed = uniform_probability)
  ))
  # The table is ages by length bins, or a list of 1 table per year.
  fleet_conversion <- function(fleet, fleet_data) {
    initialize_fims(
      parameters = default_parameters,
      data = fleet_data
    )[["model_data"]][["fleets"]][[fleet]][["age_to_length_conversion"]]
  }
  shared_values <- model_age_to_length_conversion(data)
  #' @description Test that `initialize_fims()` uses a fleet's own age-to-length conversion rows when it has them.
  expect_equal(
    c(t(fleet_conversion("fleet1", fleet_data))),
    rep(uniform_probability, length(shared_values))
  )
  #' @description Test that `initialize_fims()` uses the shared age-to-length conversion rows for a fleet without its own.
  expect_equal(c(t(fleet_conversion("survey1", fleet_data))), shared_values)

  # Year 5 gets a uniform table and every other year keeps the default.
  year_data <- FIMSFrame(dplyr::bind_rows(
    data_big,
    dplyr::mutate(conversion, timing = 5, observed = uniform_probability)
  ))
  by_year <- fleet_conversion("fleet1", year_data)
  #' @description Test that `initialize_fims()` passes 1 age-to-length conversion table per year when a year has its own rows.
  expect_equal(c(t(by_year[[5]])), rep(uniform_probability, length(shared_values)))
  #' @description Test that `initialize_fims()` passes the default age-to-length conversion table for years without their own rows.
  expect_equal(c(t(by_year[[4]])), shared_values)

  # Expected length compositions for fleet1, 1 column per year.
  fleet1_length_comp <- function(fims_frame) {
    fit <- suppressWarnings(fit_fims(
      initialize_fims(setup_default_parameters(data = fims_frame), fims_frame),
      optimize = FALSE
    ))
    matrix(
      get_report(fit)[["lengthcomp_proportion"]][[1]],
      ncol = get_n_years(fims_frame)
    )
  }
  base_comp <- fleet1_length_comp(data)
  year_comp <- fleet1_length_comp(year_data)
  #' @description Test that a uniform year-5 age-to-length conversion table gives a uniform expected length composition in year 5 only.
  expect_equal(
    year_comp[, 5],
    rep(uniform_probability, nrow(year_comp)),
    tolerance = 1e-8
  )
  #' @description Test that a year-5 age-to-length conversion table leaves the expected length composition in other years unchanged.
  expect_equal(year_comp[, 4], base_comp[, 4])
})

test_that("`initialize_fims()` assigns named von Bertalanffy SDs independently of row order", {
  growth <- setup_default_Growth(
    data = data,
    module_type = "VonBertalanffySchnute"
  ) |>
    dplyr::mutate(
      value = dplyr::case_when(
        label == "reference_age_for_length_young" ~ 4,
        label == "reference_age_for_length_old" ~ 18,
        label == "length_at_age_sd_young" ~ 31,
        label == "length_at_age_sd_old" ~ 79,
        TRUE ~ value
      )
    ) |>
    dplyr::slice(dplyr::n():1)
  parameters <- default_parameters |>
    dplyr::filter(module_name != "Growth") |>
    dplyr::bind_rows(growth)

  #' @description Test that named SD inputs initialize without warnings after changing reference ages and reversing row order.
  expect_no_warning(
    result <- initialize_fims(parameters = parameters, data = data)
  )

  # The SDs are passed on the log scale, as FIMS estimates them.
  model_parameters <- result[["parameters"]]
  #' @description Test that each SD is assigned to its named parameter.
  expect_equal(exp(model_parameters[["Growth.log_length_at_age_sd_young"]]), 31)
  expect_equal(exp(model_parameters[["Growth.log_length_at_age_sd_old"]]), 79)
  population <- result[["model_data"]][["populations"]][["population"]]
  #' @description Test that each reference age is assigned to its named input.
  expect_equal(population[["growth_inputs"]][["reference_ages"]], c(4, 18))
})

## Edge handling ----
test_that("`initialize_fims()` works with edge cases", {
  # Number of estimated values, fixed and random, as RTMB sees them.
  n_estimated <- function(input) {
    input[["map"]] |>
      purrr::map_int(\(map) sum(!is.na(map))) |>
      sum()
  }
  modified_log_devs <- default_parameters |>
    dplyr::filter(label == "log_devs") |>
    # change first 10 estimation_type for label of log_devs from
    # random_effects to constant
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        timing <= 11,
        "constant",
        estimation_type
      ),
      distribution_type = dplyr::if_else(
        timing <= 11,
        NA_character_,
        distribution_type
      ),
      distribution = dplyr::if_else(
        timing <= 11,
        NA_character_,
        distribution
      )
    )

  parameters_multiple_types <- default_parameters |>
    # Remove rows where label is "log_devs" but keep the rows where label is NA
    dplyr::filter(label != "log_devs" | is.na(label)) |>
    dplyr::bind_rows(modified_log_devs)
  init_parm_default <- initialize_fims(
    parameters = default_parameters,
    data = data
  )
  #' @description Test that `initialize_fims()` warns when some process values are constant but still included in the process distribution.
  expect_warning(
    init_parm_multiple_types <- initialize_fims(
      parameters = parameters_multiple_types,
      data = data
    ),
    regexp = "10 of the 29"
  )
  #' @description Test that `initialize_fims()` works with multiple estimation types.
  expect_equal(
    n_estimated(init_parm_multiple_types),
    n_estimated(init_parm_default) - 10
  )

  parameters_na_types <- parameters_multiple_types |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        label == "log_devs" & estimation_type == "constant",
        NA_character_,
        estimation_type
      )
    )
  #' @description Test that `initialize_fims()` treats an NA estimation_type in `log_devs` as constant and warns instead of erroring.
  expect_warning(
    initialize_fims(parameters = parameters_na_types, data = data),
    regexp = "10 of the 29"
  )

  missing_recruitment_distribution <- setup_default_parameters(data = data) |>
    dplyr::filter(module_name != "Recruitment") |>
    dplyr::bind_rows(
      setup_default_Recruitment(
        data = data,
        distribution = NA_character_
      )
    )
  init_parm_missing_distribution <- initialize_fims(
    parameters = missing_recruitment_distribution,
    data = data
  )
  estimated_names <- init_parm_missing_distribution[["map"]] |>
    purrr::keep(\(map) any(!is.na(map))) |>
    names()

  #' @description Test that 'log_sd' is not estimated when there is no distribution specified for recruitment.
  expect_equal(grep(pattern = "log_sd", estimated_names), integer(0))

  #' @description Test that 'log_devs' are not estimated when there is no distribution specified for recruitment.
  expect_equal(grep(pattern = "log_devs", estimated_names), integer(0))

  #' @description Test that 'log_devs' are not random effects when there is no distribution specified for recruitment.
  expect_equal(
    grep(pattern = "log_devs", init_parm_missing_distribution[["random"]]),
    integer(0)
  )

  #' @description Test that there is no returned recruitment nll when there is no distribution specified for recruitment.
  report <- init_parm_missing_distribution |>
    fit_fims(optimize = FALSE) |>
    get_report()
  expect_equal(report[["nll_components"]] |> length(), 6)
})

test_that("`initialize_fims()` holds a process's own parameters constant when no process uses them", {
  withr::local_options(rlib_message_verbosity = "default")
  is_survey_log_q <- function(parameters) {
    parameters[["label"]] == "log_q" & parameters[["fleet"]] %in% "survey1"
  }
  # A process on survey1's log_q, then the process removed from the log_q
  # rows but not its own mean and sd rows.
  parameters <- default_parameters |>
    add_process(
      log_q ~ 1 + (1 | year),
      module_name = "Fleet",
      fleet = "survey1"
    )
  parameters <- parameters |>
    dplyr::mutate(
      distribution_type = dplyr::if_else(
        is_survey_log_q(parameters), NA_character_, distribution_type
      ),
      distribution = dplyr::if_else(
        is_survey_log_q(parameters), NA_character_, distribution
      ),
      re_structure = dplyr::if_else(
        is_survey_log_q(parameters), NA_character_, re_structure
      ),
      estimation_type = dplyr::if_else(
        is_survey_log_q(parameters), "fixed_effects", estimation_type
      )
    )
  #' @description Test that `initialize_fims()` says which process parameters no process uses.
  expect_message(
    object = input <- initialize_fims(parameters = parameters, data = data),
    regexp = "not used by any process"
  )
  #' @description Test that `initialize_fims()` holds an unused process sd at its starting value, so it is not estimated.
  expect_true(all(is.na(input[["map"]][["Fleet.survey1.log_q_log_sd"]])))
  #' @description Test that `initialize_fims()` holds an unused process mean at its starting value, so it is not estimated.
  expect_true(all(is.na(
    input[["map"]][["Fleet.survey1.log_q_expected_mean"]]
  )))

  # With no recruitment process, a prior on the recruitment log_sd is its
  # only use, so the log_sd is still estimated.
  is_recruitment_process <- function(parameters) {
    parameters[["module_name"]] == "Recruitment" &
      parameters[["label"]] %in% c("log_devs", "log_sd")
  }
  no_process <- default_parameters |>
    dplyr::mutate(
      distribution_type = dplyr::if_else(
        is_recruitment_process(default_parameters), NA_character_,
        distribution_type
      ),
      distribution = dplyr::if_else(
        is_recruitment_process(default_parameters), NA_character_,
        distribution
      ),
      estimation_type = dplyr::case_when(
        module_name == "Recruitment" & label == "log_devs" ~ "constant",
        module_name == "Recruitment" & label == "log_sd" ~ "fixed_effects",
        .default = estimation_type
      )
    ) |>
    add_priors(
      log_sd ~ normal(mean = log(0.4), sd = 0.2),
      module_name = "Recruitment"
    )
  prior_input <- initialize_fims(parameters = no_process, data = data)
  #' @description Test that `initialize_fims()` keeps estimating a parameter whose only use is a prior.
  expect_false(anyNA(prior_input[["map"]][["Recruitment.log_sd"]]))
})

test_that("`initialize_fims()` treats a catch of 0 as a year with no fishing", {
  zero_catch <- dplyr::mutate(
    data_big,
    observed = dplyr::if_else(type == "catch" & timing == 3, 0, observed)
  )
  zero_catch_frame <- FIMSFrame(zero_catch)
  likelihoods <- initialize_fims(
    parameters = setup_default_parameters(zero_catch_frame),
    data = zero_catch_frame
  )[["model_data"]][["likelihoods"]]
  names(likelihoods) <- purrr::map_chr(likelihoods, "name")
  #' @description Test that `initialize_fims()` leaves a catch of 0 out of the likelihood.
  expect_true(is.na(likelihoods[["fleet1_catch"]][["observed"]][3]))

  get_objective <- function(data, parameters) {
    fit <- parameters |>
      initialize_fims(data = data) |>
      fit_fims(optimize = FALSE)
    list(
      jnll = get_report(fit)[["jnll"]],
      gradient = get_obj(fit)[["gr"]]()
    )
  }
  default_objective <- get_objective(
    zero_catch_frame,
    setup_default_parameters(zero_catch_frame)
  )
  # The manual workaround: catch as missing and F fixed at -200 by hand.
  missing_catch_frame <- dplyr::mutate(
    zero_catch,
    observed = dplyr::if_else(type == "catch" & observed == 0, -999, observed)
  ) |>
    FIMSFrame()
  manual_objective <- get_objective(
    missing_catch_frame,
    setup_default_parameters(missing_catch_frame) |>
      dplyr::mutate(
        fix_year = .data[["label"]] == "log_Fmort" &
          .data[["fleet"]] == "fleet1" &
          .data[["timing"]] == 3,
        value = dplyr::if_else(.data[["fix_year"]], -200, .data[["value"]]),
        estimation_type = dplyr::if_else(
          .data[["fix_year"]],
          "constant",
          .data[["estimation_type"]]
        )
      ) |>
      dplyr::select(-"fix_year")
  )

  #' @description Test that a catch of 0 gives a finite objective and gradient.
  expect_true(is.finite(default_objective[["jnll"]]))
  expect_true(all(is.finite(default_objective[["gradient"]])))
  #' @description Test that a catch of 0 gives the same objective as dropping the catch and fixing F by hand.
  expect_equal(default_objective[["jnll"]], manual_objective[["jnll"]])

  #' @description Test that `initialize_fims()` warns when F is estimated in a year with a catch of 0.
  expect_warning(
    initialize_fims(
      parameters = setup_default_parameters(data),
      data = zero_catch_frame
    ),
    regexp = "catch of 0:\\s+\"fleet1 3\""
  )
})

## Error handling ----
test_that("`initialize_fims()` returns correct error messages", {
  #' @description Test that `initialize_fims()` handles missing parameters input correctly.
  expect_error(
    initialize_fims(data = data),
    "The `parameters` argument must be a tibble."
  )

  #' @description Test that `initialize_fims()` handles non-list parameters input correctly.
  expect_error(
    initialize_fims(parameters = "not_a_list", data = data),
    "The `parameters` argument must be a tibble."
  )

  parameters_no_fleets <- default_parameters |>
    dplyr::filter(!(fleet %in% c("fleet1", "survey1")))
  #' @description Test that `initialize_fims()` fails when no fleets are provided.
  expect_error(
    initialize_fims(parameters = parameters_no_fleets, data = data),
    "No fleets found in the provided `parameters`"
  )

  parameters_wrong_type <- default_parameters |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        estimation_type == "fixed_effects",
        "fixed.effects",
        estimation_type
      )
    )
  #' @description Test that `initialize_fims()` correctly returns an error on an unknown estimation_type.
  expect_error(
    initialize_fims(parameters = parameters_wrong_type, data = data),
    "The `estimation_type` must be one of: constant, fixed_effects, and random_effects."
  )
})

test_that("`initialize_fims()` returns correct error messages for the recruitment process", {
  missing_recruitment_distribution <- default_parameters |>
    dplyr::filter(module_name != "Recruitment") |>
    dplyr::bind_rows(
      setup_default_Recruitment(
        data = data,
        distribution = NA_character_
      )
    )
  missing_recruitment_distribution_error <-
    missing_recruitment_distribution |>
    dplyr::rows_update(
      y = tibble::tibble(
        module_name = "Recruitment",
        label = "log_devs",
        timing = 2:get_n_years(data),
        estimation_type = "random_effects"
      ),
      by = c("module_name", "label", "timing")
    )

  #' @description Test that `initialize_fims()` returns correct error with distribution estimation type mismatch.
  expect_error(
    missing_recruitment_distribution_error |>
      initialize_fims(data = data),
    "Missing required inputs for recruitment process"
  )

  mismatch_error <- default_parameters |>
    dplyr::rows_update(
      y = tibble::tibble(
        module_name = "Recruitment",
        label = "log_devs",
        timing = 2:get_n_years(data),
        estimation_type = "constant"
      ),
      by = c("module_name", "label", "timing")
    )

  #' @description Test that `initialize_fims()` handles missing distribution for recruitment correctly.
  expect_error(
    mismatch_error |>
      initialize_fims(data = data),
    "Missing required inputs for recruitment process"
  )
})

test_that("`initialize_fims()` errors for a catch unit it cannot map", {
  #' @description Test that `initialize_fims()` errors rather than fitting a catch unit with no mapping, e.g., one added to FIMSFrame() but not to initialize_fleet().
  frame <- FIMSFrame(data_big)
  # FIMSFrame() rejects this unit, so it is set on the stored data directly
  frame@data[["unit"]][frame@data[["type"]] == "catch"] <- "t"
  expect_error(
    object = setup_default_parameters(frame) |>
      initialize_fims(data = frame),
    regexp = "which the model cannot use"
  )
})

test_that("`initialize_fims()` rejects malformed named von Bertalanffy SD inputs", {
  growth <- setup_default_Growth(
    data = data,
    module_type = "VonBertalanffySchnute"
  )
  young <- which(growth[["label"]] == "length_at_age_sd_young")
  old <- which(growth[["label"]] == "length_at_age_sd_old")

  duplicate <- growth
  duplicate[["label"]][old] <- "length_at_age_sd_young"

  age_labeled <- growth
  age_labeled[["age"]][young] <- 4

  cases <- list(
    missing_young = growth[-young, ],
    missing_old = growth[-old, ],
    duplicate_young = duplicate,
    unexpected_age = age_labeled
  )

  #' @description Test that interpolation requires 1 SD of each name and no separate age labels.
  for (case in names(cases)) {
    parameters <- default_parameters |>
      dplyr::filter(module_name != "Growth") |>
      dplyr::bind_rows(cases[[case]])
    expect_error(
      initialize_fims(parameters = parameters, data = data),
      regexp = "interpolation-based variability inputs are malformed",
      info = case
    )
  }
})

test_that("`initialize_fims()` rejects growth correlations that are not a correlation matrix", {
  growth <- setup_default_Growth(
    data = data,
    module_type = "VonBertalanffySchnute"
  )
  interpolation_rows <- growth[["label"]] %in%
    c("length_at_age_sd_young", "length_at_age_sd_old")
  # The delta-method option: 3 sds on the log scale and 3 correlations on a
  # logit scale bounded by -1 and 1.
  delta_rows <- function(correlations) {
    growth[rep(which(interpolation_rows)[1], 6), ] |>
      dplyr::mutate(
        label = c(
          "log_sd_mean_length_young", "log_sd_mean_length_old",
          "log_sd_growth_coefficient",
          "mean_length_young_mean_length_old_logit_corr",
          "mean_length_young_growth_coefficient_logit_corr",
          "mean_length_old_growth_coefficient_logit_corr"
        ),
        value = c(log(c(0.05, 0.05, 0.05)), logit(-1, 1, correlations)),
        estimation_type = "constant"
      )
  }
  parameters_with <- function(correlations) {
    default_parameters |>
      dplyr::filter(module_name != "Growth") |>
      dplyr::bind_rows(growth[!interpolation_rows, ], delta_rows(correlations))
  }
  #' @description Test that `initialize_fims()` accepts growth correlations that form a valid correlation matrix.
  expect_no_error(
    initialize_fims(parameters = parameters_with(c(0.5, 0.2, 0.1)), data = data)
  )
  #' @description Test that `initialize_fims()` errors for correlations of 0.9, 0.9 and -0.9, whose correlation matrix has a negative determinant.
  expect_error(
    initialize_fims(parameters = parameters_with(c(0.9, 0.9, -0.9)), data = data),
    regexp = "positive\\s+semi-definite"
  )
})

test_that("`initialize_fims()` errors when composition data do not match the expected dimensions", {
  bad_data <- data
  bad_data@data <- bad_data |>
    get_data() |>
    dplyr::filter(!(type == "age_comp" & age == 2))
  #' @description Test that `initialize_fims()` correctly returns error when there are missing bins for a given fleet.
  expect_error(
    initialize_fims(parameters = default_parameters, data = bad_data),
    "does not match the expected dimensions"
  )
  bad_data@data <- data |>
    get_data() |>
    dplyr::filter(!(type == "weight_at_age" & age == 2))
  #' @description Test that `initialize_fims()` returns an error rather than recycling weight at age when an age is missing.
  expect_error(
    initialize_fims(parameters = default_parameters, data = bad_data),
    "not 1 per year and age"
  )
})
